function run(inputExcecoes) {
	try {
		const obj = JSON.parse(inputExcecoes)
		const inputContent = obj.inputContent;

		if (!inputContent || inputContent === "") {
			return "INATIVIDADE"
		}

		return inputContent;
	} catch (error) {
		return "ERROR_GET_INPUT_CONTENT"
	}
}

function run(inputExcecoes) {
	try {
		const obj = JSON.parse(inputExcecoes)
		const inputContent = obj.inputContent;

		if (!inputContent || inputContent === "") {
			return "INATIVIDADE"
		}

		return inputContent;
	} catch (error) {
		return "ERROR_GET_INPUT_CONTENT"
	}
}

const run = (objUserInput) => {
    try {
        let content = "";

        try {
            const parsed = JSON.parse(objUserInput);

            if (parsed && parsed.userInput && parsed.userInput.content) {
                content = parsed.userInput.content;
            } else if (parsed && parsed.content) {
                content = parsed.content;
            } else {
                content = String(objUserInput || "");
            }
        } catch (error) {
            content = String(objUserInput || "");
        }

        let objCleanedUserInput = {
            baseInput: content,
            cleanedInput: content,
            hasEmojiTracking: "Nao"
        };

        if (content.match(EMOJI_REGEX)) {
            objCleanedUserInput.hasEmojiTracking = "Sim";
        }

        objCleanedUserInput.cleanedInput = content
            .replace(EMOJI_REGEX, "")
            .trim();

        return objCleanedUserInput;
    } catch (error) {
        return {
            baseInput: "",
            cleanedInput: "",
            hasEmojiTracking: "Nao"
        };
    }
};

const EMOJI_REGEX = /(\u00a9|\u00ae|[\u2000-\u3300]|\ud83c[\ud000-\udfff]|\ud83d[\ud000-\udfff]|\ud83e[\ud000-\udfff])/g;

const run = (contador) => {
    try {
        if (!contador) {
            return 1;
        }

        return parseInt(Number(contador)) + 1;

    } catch (e) {
        return 1;
    }
};

function run(input) {
    try {
        const data = typeof input === "string"
            ? JSON.parse(input)
            : input;

        if (
            !data ||
            !data.resource ||
            !Array.isArray(data.resource.intentions) ||
            data.resource.intentions.length === 0
        ) {
            return "{}";
        }

        const intention = data.resource.intentions[0];

        return JSON.stringify({
            id: intention.id,
            name: intention.name,
            score: intention.score
        });

    } catch (e) {
        return "{}";
    }
}

function run(input) {
  try {
    let opcoesMenu = {
      "1": "Sim",
      "2": "Não",
      "3": "Menu inicial"
    };

    let menuRegex = {
      "1": /\b(?:sim|claro|confirmo|positivo|ok|okay|pode\s+ser|aceito|quero|continuar|sair|finalizar)\b/i,

      "2": /\b(?:n[aã]o|negativo|cancelar|desistir|prefiro\s+n[aã]o|encerrar|parar)\b/i,

      "3": /(?:#menu|\bmenu\s*inicial\b|\bin[ií]cio\b|\bcome[cç]ar\b|\breiniciar\b|\bvoltar\b|\bhome\b)/i
    };

    input = input.trim();

    for (let prop in menuRegex) {
      if (menuRegex[prop].test(input)) {
        return opcoesMenu[prop];
      }
    }

    return "Input inesperado";
  } catch (error) {
    return "Input inesperado";
  }
}

function run(horaEntrada, horaFim) {
  try {
    function parseDataGMT0(dataTexto) {
      const [data, hora] = dataTexto.split(" ");
      const [mes, dia, ano] = data.split("/");
      const [hh, mm, ss] = hora.split(":");

      return new Date(Date.UTC(ano, mes - 1, dia, hh, mm, ss));
    }

    function formatarBrasil(data) {
      const dataBrasil = new Date(data.getTime() - 3 * 60 * 60 * 1000);

      const dia = String(dataBrasil.getUTCDate()).padStart(2, "0");
      const mes = String(dataBrasil.getUTCMonth() + 1).padStart(2, "0");
      const ano = dataBrasil.getUTCFullYear();

      const hora = String(dataBrasil.getUTCHours()).padStart(2, "0");
      const minuto = String(dataBrasil.getUTCMinutes()).padStart(2, "0");

      return {
        data: `${dia}/${mes}/${ano}`,
        hora: `${hora}:${minuto}`
      };
    }

    const entrada = parseDataGMT0(horaEntrada);
    const fim = parseDataGMT0(horaFim);

    const diferencaMs = fim - entrada;
    const totalSegundos = Math.floor(diferencaMs / 1000);
    const totalMinutos = Math.floor(totalSegundos / 60);

    const horas = Math.floor(totalMinutos / 60);
    const minutos = totalMinutos % 60;
    const segundos = totalSegundos % 60;

    const entradaFormatada = formatarBrasil(entrada);
    const fimFormatada = formatarBrasil(fim);

    let tempoTexto = "";

    if (horas > 0) {
      tempoTexto += `${horas} ${horas === 1 ? "hora" : "horas"}`;
    }

    if (minutos > 0) {
      if (tempoTexto) tempoTexto += " e ";
      tempoTexto += `${minutos} ${minutos === 1 ? "minuto" : "minutos"}`;
    }

    if (horas === 0 && minutos === 0) {
      tempoTexto = `${segundos} ${segundos === 1 ? "segundo" : "segundos"}`;
    }

    return {
      horaEntrada,
      horaFim,
      tempoInteracao: {
        horas,
        minutos,
        segundos,
        totalMinutos,
        totalSegundos
      },
      relatorio: `Entrou às ${entradaFormatada.hora} do dia ${entradaFormatada.data} finalizou interação às ${fimFormatada.hora} do dia ${fimFormatada.data} tempo de interação de ${tempoTexto}`
    };
  } catch (error) {
    return {
      erro: "Erro ao calcular tempo de interação"
    };
  }
}

