/**
 * Detecção de intenções de small talk por dicionário.
 * Compatível com Node e com o "Executar script" do Blip.
 * Todas as funções têm try/catch: em caso de falha, retornam um valor neutro
 * (texto vazio, "sem match" ou "None") em vez de interromper o fluxo.
 */

let INTENTS = {
  Greeting: ["oi", "ei", "oii", "oir", "olá", "alô", "olar", "olarr", "oal", "Psiu", "Hi", "hello", "helo", "eaí", "eae", "e aí", "fala", "prezado", "prezados", "opa"],
  GoodMorning: ["oi bom dia", "Bom dia", "bom di", "bodia", "bondia", "bondinha", "bomdia", "bmdia", "bom diaa", "bomndia"],
  GoodAfternoon: ["boa tarde", "bo tarde", "bontarde", "bontardee", "bontard", "boa tader", "bopa tarde"],
  GoodNight: ["Boa noite", "bopa noite", "boa noit", "buenas noches", "boas noite", "buenas noit", "buenas noitess"],
  Cordiality: ["atenciosamente", "cordialmente", "respeitosamente", "com consideração", "com estima", "com apreço", "com respeito", "tudo bem?", "como está?", "Eae, beleza? E aí, blz?", "tudo bom?", "como vai?", "tudo certo?"],
  Elogio: ["massa", "incrível", "parabéns", "arrasou", "sensacional", "gosto", "maravilhoso", "ótimo", "excelente", "topster", "curti", "boa"],
  Despedida: ["tchau", "até mais", "até logo", "até breve", "até a próxima", "até já", "até amanhã", "até depois", "até já já", "até mais ver", "inté", "até", "bye", "bye bye", "see you", "see u", "cya", "adeus", "Xau", "Tchauí", "Falou", "flw", "Falows", "Esou de saída", "Vai pela sombra"],
  Agradecimento: ["obrigado", "obrigada", "agradecido", "agradecida", "muito obrigado", "muito obrigada", "valeu", "grato", "grata", "agradeço", "agradecemos", "Isso é top!", "Muito top!", "muito legal", "Bom!", "Ótimo!"],
  Cursed: ["merda", "porra", "caralho", "puta que pariu", "foda-se", "foda", "fodase", "fudido", "fodido", "fuder", "fudeu", "fudendo", "fudida"],
  Disagreement: ["discordo", "não concordo", "discordamos", "discorda", "discordam", "discordar", "Não me interessa", "Não era isso", "Não tenho interesse", "Assim não precisa", "De forma alguma", "De jeito nenhum", "Nunca", "Jamais"],
  Confirmation: ["sim", "claro", "com certeza", "certamente", "afirmativo", "positivo", "exatamente", "perfeitamente", "concordo", "de acordo", "ok", "okay", "okey", "Beleza", "Beleza então", "Está bem", "Está bom", "Blz", "Aceito"]
};

// Intenções em que NÃO aceitamos match aproximado (evita "porta" -> "porra").
let FUZZY_DISABLED = { Cursed: true };

let ACCENTS = {
  "á": "a", "à": "a", "â": "a", "ã": "a", "ä": "a",
  "é": "e", "è": "e", "ê": "e", "ë": "e",
  "í": "i", "ì": "i", "î": "i", "ï": "i",
  "ó": "o", "ò": "o", "ô": "o", "õ": "o", "ö": "o",
  "ú": "u", "ù": "u", "û": "u", "ü": "u",
  "ç": "c", "ñ": "n"
};

function normalize(text) {
  try {
    let s = String(text == null ? "" : text).toLowerCase();
    s = s.replace(/[áàâãäéèêëíìîïóòôõöúùûüçñ]/g, function (c) { return ACCENTS[c] || c; });
    s = s.replace(/[^a-z0-9\s]/g, " ");   // pontuação, emojis, hífen -> espaço
    s = s.replace(/(.)\1{2,}/g, "$1$1");  // "oiiiii" -> "oii", "bom diaaaa" -> "bom diaa"
    return s.replace(/\s+/g, " ").replace(/^\s+|\s+$/g, "");
  } catch (e) {
    return "";
  }
}

// Distância de edição máxima tolerada, pelo tamanho da frase (sem espaços).
function maxDistance(len) {
  try {
    len = Number(len) || 0;
    if (len < 6) return 0;  // palavras curtas ("oi", "sim", "boa") só batem exato
    if (len < 10) return 1;
    return 2;
  } catch (e) {
    return 0;
  }
}

function levenshtein(a, b, limit) {
  try {
    a = String(a == null ? "" : a);
    b = String(b == null ? "" : b);
    limit = Number(limit) || 0;
    if (Math.abs(a.length - b.length) > limit) return limit + 1;
    let prev = [], curr, i, j;
    for (j = 0; j <= b.length; j++) prev[j] = j;
    for (i = 1; i <= a.length; i++) {
      curr = [i];
      let rowMin = i;
      for (j = 1; j <= b.length; j++) {
        let cost = a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1;
        curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
        if (curr[j] < rowMin) rowMin = curr[j];
      }
      if (rowMin > limit) return limit + 1; // corte antecipado
      prev = curr;
    }
    return prev[b.length];
  } catch (e) {
    return (Number(limit) || 0) + 1; // em caso de falha, considera "não bateu"
  }
}

// Índice pré-processado (uma vez só)
let INDEX = (function () {
  let list = [], seen = {};
  try {
    for (let rawIntent in INTENTS) {
      if (!Object.prototype.hasOwnProperty.call(INTENTS, rawIntent)) continue;
      let intent = rawIntent.replace(/^\s+|\s+$/g, ""); // trata "Confirmation " com espaço
      let phrases = INTENTS[rawIntent] || [];
      for (let p = 0; p < phrases.length; p++) {
        try {
          let norm = normalize(phrases[p]);
          if (!norm || seen[intent + "|" + norm]) continue;
          seen[intent + "|" + norm] = true;
          list.push({
            intent: intent,
            phrase: norm,
            compact: norm.replace(/ /g, ""),
            tokens: norm.split(" ").length
          });
        } catch (e) {
          // ignora só a frase com problema e segue com as demais
        }
      }
    }
  } catch (e) {
    // retorna o que conseguiu indexar até aqui
  }
  return list;
})();

/**
 * Detecta as intenções presentes no texto.
 * @returns {{intent: string|null, matched: string|null, score: number,
 *            coverage: number, intents: string[], matches: Array}}
 *   - intent:   intenção principal (a maior frase encontrada), ou null
 *   - coverage: fração do texto (0..1) explicada por intenções. Se for < 1,
 *               a mensagem tem conteúdo além do small talk (ex.: "oi, quero meu boleto").
 *   - intents:  todas as intenções encontradas, na ordem em que aparecem
 *   - error:    presente apenas se ocorrer uma falha inesperada
 */
function detectIntent(input) {
  let normalized = normalize(input);
  let empty = { input: normalized, intent: null, matched: null, score: 0, coverage: 0, intents: [], matches: [] };

  try {
    if (!normalized) return empty;

    let tokens = normalized.split(" ");
    let candidates = [];
    let t;

    for (let k = 0; k < INDEX.length; k++) {
      let entry = INDEX[k];
      let limit = FUZZY_DISABLED[entry.intent] ? 0 : maxDistance(entry.compact.length);
      // janelas de tamanho n-1..n+1 para pegar "bomdia" x "bom dia" e vice-versa
      let minSize = Math.max(1, entry.tokens - 1), maxSize = entry.tokens + 1;
      for (let size = minSize; size <= maxSize; size++) {
        for (let start = 0; start + size <= tokens.length; start++) {
          let window = tokens.slice(start, start + size).join("");
          let dist = window === entry.compact ? 0 : (limit ? levenshtein(window, entry.compact, limit) : 1);
          if (dist <= limit) {
            candidates.push({
              intent: entry.intent,
              phrase: entry.phrase,
              text: tokens.slice(start, start + size).join(" "),
              start: start,
              end: start + size,
              length: entry.compact.length,
              distance: dist,
              score: 1 - dist / entry.compact.length
            });
          }
        }
      }
    }

    // Escolha gulosa sem sobreposição: primeiro quem cobre mais palavras, depois o
    // match mais exato. Assim "boa tarde" vence "boa" (Elogio), "oi bom dia" vence
    // "oi" (Greeting) e "boa tarde" exato vence "bopa tarde" aproximado.
    candidates.sort(function (a, b) {
      return ((b.end - b.start) - (a.end - a.start)) || (a.distance - b.distance) ||
             (b.length - a.length) || (a.start - b.start);
    });
    let used = [], accepted = [];
    for (let c = 0; c < candidates.length; c++) {
      let cand = candidates[c], free = true;
      for (t = cand.start; t < cand.end; t++) if (used[t]) { free = false; break; }
      if (!free) continue;
      for (t = cand.start; t < cand.end; t++) used[t] = true;
      accepted.push(cand);
    }
    if (!accepted.length) return empty;

    let primary = accepted[0];
    accepted.sort(function (a, b) { return a.start - b.start; });

    let intents = [], covered = 0, total = 0;
    for (let a = 0; a < accepted.length; a++) {
      if (intents.indexOf(accepted[a].intent) === -1) intents.push(accepted[a].intent);
    }
    for (t = 0; t < tokens.length; t++) {
      total += tokens[t].length;
      if (used[t]) covered += tokens[t].length;
    }

    return {
      input: normalized,
      intent: primary.intent,
      matched: primary.phrase,
      score: Math.round(primary.score * 100) / 100,
      coverage: total ? Math.round((covered / total) * 100) / 100 : 0,
      intents: intents,
      matches: accepted
    };
  } catch (e) {
    empty.error = e && e.message ? e.message : String(e);
    return empty;
  }
}

// Extrai o texto digitado: aceita JSON ({ inputContent: "..." }), objeto ou texto puro.
function extractInput(userInput) {
  try {
    if (userInput == null) return "";
    if (typeof userInput === "object") return userInput.inputContent != null ? String(userInput.inputContent) : "";
    let raw = String(userInput);
    try {
      let parsed = JSON.parse(raw);
      if (parsed && typeof parsed === "object") return parsed.inputContent != null ? String(parsed.inputContent) : "";
      return String(parsed);
    } catch (e) {
      return raw; // não era JSON: usa o texto como veio
    }
  } catch (e) {
    return "";
  }
}

// Uso no Blip ("Executar script"): mapeie a variável de entrada e a de saída.
// Retorna a intenção principal ou "None".
function run(userInput) {
  try {
    let input = extractInput(userInput);
    let r = detectIntent(input);
    return (r && r.intent) || "None";
  } catch (e) {
    return "None";
  }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { detectIntent: detectIntent, normalize: normalize, run: run, INTENTS: INTENTS };
}
